def test_word_candidates_includes_new_awareness_bases() -> None:
    """_word_candidates includes -ity/-ability, -ily/-ly, -ment, -ency bases. TDD: plan. Edited by Cursor."""
    cand_ind = _word_candidates("indigency")
    assert "indigent" in cand_ind, "indigency candidates should include indigent"
    cand_admin = _word_candidates("administrability")
    assert "administrable" in cand_admin, (
        "administrability candidates should include administrable"
    )
    cand_disc = _word_candidates("discriminatorily")
    assert "discriminatory" in cand_disc, (
        "discriminatorily candidates should include discriminatory"
    )
    cand_arb = _word_candidates("arbitrability")
    assert "arbitrable" in cand_arb, (
        "arbitrability candidates should include arbitrable"
    )
    assert "arbiter" in cand_arb, "arbitrability candidates should include arbiter stem"
