    assert "enplane" in cand_enp, "enplanement candidates should include enplane"
    cand_rout = _word_candidates("routinization")
    assert "routinize" in cand_rout, "routinization candidates should include routinize"
    cand_disch = _word_candidates("dischargability")
    assert "dischargeable" in cand_disch, (
        "dischargability candidates should include dischargeable"
    )


